public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Loads more active stories from a story list. The loaded stories will be sent through updates. Active stories are sorted by
    /// the pair (active_stories.order, active_stories.story_poster_chat_id) in descending order. Returns a 404 error if all active stories have been loaded
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> LoadActiveStoriesAsync(StoryList storyList = default)
    {

           using var activity =  StartCallActivity("LoadActiveStoriesAsync", typeof(LoadActiveStories).FullName ?? "LoadActiveStoriesAsync");

           try
           {
             return client.LoadActiveStoriesAsync(storyList);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
